// ─────────────────────────────────────────────────────────────────────────────
// CONFIGURAÇÃO
// OFFSET_DIAS = 1  → verifica o DIA SEGUINTE à data da execução (produção)
// Para testar outra data, mude o valor (ex.: 3 = daqui a 3 dias)
// ─────────────────────────────────────────────────────────────────────────────
const OFFSET_DIAS = 1;

const tz = 'America/Sao_Paulo';
const agora = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
function pad(v){ return String(v).padStart(2, '0'); }

const alvo = new Date(agora);
alvo.setDate(alvo.getDate() + OFFSET_DIAS);

const yyyy = alvo.getFullYear();
const mm   = pad(alvo.getMonth() + 1);
const dd   = pad(alvo.getDate());

const mesNome   = alvo.toLocaleDateString('pt-BR', { timeZone: tz, month: 'long' });
const diaSemana = alvo.toLocaleDateString('pt-BR', { timeZone: tz, weekday: 'long' });

function normalize(s = '') {
  return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

return [{ json: {
  offset_dias: OFFSET_DIAS,
  eh_amanha: OFFSET_DIAS === 1,
  alvo_ymd: `${yyyy}-${mm}-${dd}`,
  alvo_ddmmyyyy: `${dd}/${mm}/${yyyy}`,
  dd, mm, yyyy,
  dia_semana: diaSemana,
  mes_nome: mesNome.toUpperCase(),
  mes_normalizado: normalize(mesNome),
  ano: String(yyyy),
  hoje_ymd: `${agora.getFullYear()}-${pad(agora.getMonth() + 1)}-${pad(agora.getDate())}`
}}];

// Escolhe a aba (guia) do mês do dia alvo na planilha de agenda.
// Aceita nomes como "JULHO", "Julho 2026", "julho/26" etc. (ignora acentos/caixa).
const ctx  = $('Code - Data Alvo').first().json;
const resp = $input.first().json;
const sheets = resp.sheets ?? resp.body?.sheets ?? [];

function normalize(s = '') {
  return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

const mes = ctx.mes_normalizado; // ex.: "julho"
const ano = ctx.ano;             // ex.: "2026"

let aba = null;
// 1ª preferência: aba que contém o mês E o ano; 2ª: aba que contém só o mês
for (const s of sheets) {
  const t = normalize(s.properties?.title || '');
  if (t.includes(mes) && t.includes(ano)) { aba = s.properties.title; break; }
}
if (!aba) {
  for (const s of sheets) {
    const t = normalize(s.properties?.title || '');
    if (t.includes(mes)) { aba = s.properties.title; break; }
  }
}

return [{ json: {
  ...ctx,
  aba,
  aba_encontrada: !!aba,
  abas_disponiveis: sheets.map(s => s.properties?.title)
}}];

const c = $input.first().json;
console.log(`Aba do mês não encontrada na agenda. Mês: ${c.mes_nome}. Abas disponíveis: ${JSON.stringify(c.abas_disponiveis)}`);
return [];

// Filtra na agenda do mês as linhas cuja coluna A (DATA) é o dia alvo.
// Colunas: A=DATA B=INÍCIO C=TÉRMINO D=DIA DA SEMANA E=ESPAÇO F=FORMADORES
//          G=TÍTULO H=ETAPAS I=COMPONENTE CURRICULAR J=PÚBLICO-ALVO
//          K=FORMATO L=VAGAS M=DIVULGAR N=GOOGLE SALA DE AULA
const ctx  = $('Code - Escolher Aba do Mês').first().json;
const resp = $input.first().json;
const matriz = resp.values ?? resp.body?.values ?? [];

function pad(v){ return String(v).padStart(2, '0'); }
function parseData(raw) {
  if (raw === null || raw === undefined || raw === '') return null;
  if (typeof raw === 'number') {
    if (raw < 20000 || raw > 60000) return null; // fora disso não é data plausível
    const ep = new Date(Date.UTC(1899, 11, 30));
    const d  = new Date(ep.getTime() + raw * 86400000);
    return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
  }
  const s  = String(raw).trim();
  const br = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (br) { let a = br[3]; if (a.length === 2) a = '20' + a; return `${a}-${pad(br[2])}-${pad(br[1])}`; }
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;
  return null;
}
function txt(v){ return (v ?? '').toString().trim(); }

const cursos = [];
for (const linha of matriz) {
  const l = linha || [];
  if (parseData(l[0]) !== ctx.alvo_ymd) continue;
  const titulo = txt(l[6]);
  if (!titulo) continue;
  cursos.push({
    DATA: txt(l[0]),
    INICIO: txt(l[1]),
    TERMINO: txt(l[2]),
    DIA_SEMANA: txt(l[3]),
    ESPACO: txt(l[4]),
    FORMADORES: txt(l[5]),
    TITULO: titulo,
    ETAPAS: txt(l[7]),
    COMPONENTE_CURRICULAR: txt(l[8]),
    PUBLICO_ALVO: txt(l[9]),
    FORMATO: txt(l[10]),
    VAGAS: txt(l[11]),
    DIVULGAR: txt(l[12]),
    GOOGLE_SALA_DE_AULA: txt(l[13])
  });
}

console.log(`Aba "${ctx.aba}" — cursos em ${ctx.alvo_ymd}: ${cursos.length}`);
return [{ json: { ...ctx, cursos, total_cursos: cursos.length, tem_curso: cursos.length > 0 } }];

const c = $input.first().json;
console.log(`Nenhum curso agendado para ${c.alvo_ddmmyyyy} (${c.dia_semana}). Nada a enviar.`);
return [];

// Casa cada curso do dia alvo com o(s) arquivo(s) da pasta do Drive.
// Os arquivos começam com "AAAA MM DD " (data de início do curso) — esse
// prefixo é ignorado e o TÍTULO precisa estar CONTIDO no restante do nome.
// Se um título casar com mais de um arquivo, todos seguem no fluxo: a
// verificação da data na aba FREQUÊNCIA decide qual(is) vale(m).
const ctx  = $('Code - Cursos do Dia Alvo').first().json;
const resp = $input.first().json;
const files = resp.files ?? resp.body?.files ?? [];

function normalize(s = '') {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').replace(/\s+/g, ' ').trim();
}
function semPrefixoData(nome) {
  const m = String(nome || '').match(/^\d{4}\s+\d{2}\s+\d{2}\s+(.*)$/);
  return m ? m[1] : String(nome || '');
}

const planilhas = files
  .filter(f => f.mimeType !== 'application/vnd.google-apps.folder' && f.name)
  .map(f => ({ id: f.id, name: f.name, nome_normalizado: normalize(semPrefixoData(f.name)) }));

const base = {
  alvo_ymd: ctx.alvo_ymd,
  alvo_ddmmyyyy: ctx.alvo_ddmmyyyy,
  dia_semana: ctx.dia_semana,
  eh_amanha: ctx.eh_amanha
};

const saida = [];
for (const curso of ctx.cursos) {
  const tituloNorm = normalize(curso.TITULO);
  const encontrados = tituloNorm
    ? planilhas.filter(p => p.nome_normalizado.includes(tituloNorm))
    : [];
  if (encontrados.length === 0) {
    console.log(`SEM ARQUIVO na pasta para o curso: ${curso.TITULO}`);
    saida.push({ json: { ...base, curso, tema: curso.TITULO, arquivo: null, arquivo_encontrado: false } });
  } else {
    for (const arq of encontrados) {
      saida.push({ json: { ...base, curso, tema: curso.TITULO,
        arquivo: { id: arq.id, name: arq.name }, arquivo_encontrado: true } });
    }
  }
}

if (saida.length === 0) {
  return [{ json: { ...base, curso: {}, tema: '', arquivo: null, arquivo_encontrado: false } }];
}
return saida;

const ctx = $input.first().json;
console.log(`Arquivo não encontrado na pasta para o curso: ${ctx.tema}`);
return [{ json: ctx }];

// 1) Confere se o dia alvo está entre as datas dos encontros da aba FREQUÊNCIA
//    (linha 2, a partir da célula L2 — L2 = data de início do curso).
// 2) Se conferir, extrai alunos (C3+ = NOME, D3+ = SCSEDUCA/e-mail) e
//    professores (aba ID: D7 = nomes, D8 = e-mails).
const cursoCtx = $('Loop - Cursos').first().json;
const alvoYmd  = cursoCtx.alvo_ymd;

const respFreq = $('HTTP - Ler Frequência').first().json;
const respId   = $input.first().json;
const matrizFreq = respFreq?.values ?? respFreq?.body?.values ?? [];
const matrizId   = respId?.values ?? respId?.body?.values ?? [];

function pad(v){ return String(v).padStart(2, '0'); }
function parseData(raw) {
  if (raw === null || raw === undefined || raw === '') return null;
  if (typeof raw === 'number') {
    if (raw < 20000 || raw > 60000) return null; // fora disso não é data plausível
    const ep = new Date(Date.UTC(1899, 11, 30));
    const d  = new Date(ep.getTime() + raw * 86400000);
    return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
  }
  const s  = String(raw).trim();
  const br = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (br) { let a = br[3]; if (a.length === 2) a = '20' + a; return `${a}-${pad(br[2])}-${pad(br[1])}`; }
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;
  return null;
}

// Localiza a linha das datas dos encontros: fica na LINHA 2 (índice 1),
// a partir da coluna L (índice 11). Por segurança, verifica também as
// linhas 1 e 3, caso alguma planilha tenha estrutura levemente diferente.
let linhaDatas = null;
for (const li of [1, 0, 2]) {
  const linha = matrizFreq[li] || [];
  for (let col = 11; col < linha.length; col++) {
    if (parseData(linha[col])) { linhaDatas = linha; break; }
  }
  if (linhaDatas) break;
}

const datasEncontros = [];
if (linhaDatas) {
  for (let col = 11; col < linhaDatas.length; col++) {
    const ymd = parseData(linhaDatas[col]);
    if (ymd) datasEncontros.push(ymd);
  }
}

const dataConfere   = datasEncontros.includes(alvoYmd);
const dataInicioYmd = datasEncontros[0] || null; // L2 = data de início do curso
const dataInicioBr  = dataInicioYmd
  ? `${dataInicioYmd.slice(8, 10)}/${dataInicioYmd.slice(5, 7)}/${dataInicioYmd.slice(0, 4)}`
  : '';

console.log(`[${cursoCtx.tema}] alvo=${alvoYmd} | datas encontros=${JSON.stringify(datasEncontros)} | confere=${dataConfere}`);

if (!dataConfere) {
  return [{ json: { ...cursoCtx, data_confere: false, alunos: [], professores: [], total_alunos: 0 } }];
}

// ── Alunos: a partir da linha 3 (índice 2) — C (índice 2)=NOME, D (índice 3)=SCSEDUCA
const alunos = [];
for (let i = 2; i < matrizFreq.length; i++) {
  const l = matrizFreq[i] || [];
  const nome  = (l[2] ?? '').toString().trim();
  const email = (l[3] ?? '').toString().trim();
  if (!email || !email.includes('@')) continue;
  alunos.push({ nome, email });
}

// ── Professores: aba ID → D7 (índice [6][3]) = nomes, D8 (índice [7][3]) = e-mails
const nomesProf  = String((matrizId[6] || [])[3] || '').split(',').map(s => s.trim()).filter(Boolean);
const emailsProf = String((matrizId[7] || [])[3] || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
let professores = nomesProf
  .map((nome, i) => ({ nome, email: emailsProf[i] || '' }))
  .filter(p => p.email);
// fallback: há e-mails mas os nomes não casaram → usa FORMADORES da agenda
if (professores.length === 0 && emailsProf.length > 0) {
  professores = emailsProf.map(e => ({ nome: cursoCtx.curso.FORMADORES || 'Formador(a)', email: e }));
}

const horario = [cursoCtx.curso.INICIO, cursoCtx.curso.TERMINO].filter(Boolean).join(' às ');

return [{ json: {
  ...cursoCtx,
  data_confere: true,
  alunos,
  total_alunos: alunos.length,
  professores,
  horario,
  data_inicio_curso: dataInicioBr || cursoCtx.alvo_ddmmyyyy
}}];

// Monta a fila de envio do curso atual: primeiro TODOS os alunos,
// depois o(s) professor(es) — o loop de destinatários processa em ordem.
const ctx = $input.first().json;
const c   = ctx.curso || {};

const prefixo    = ctx.eh_amanha ? 'amanhã, ' : '';
const textoData  = `${prefixo}${ctx.dia_semana}, dia ${ctx.alvo_ddmmyyyy}`;
const profsTexto = (ctx.professores || []).map(p => p.nome).join(', ') || c.FORMADORES || '';

const base = {
  TITULO: ctx.tema,
  DATA_INICIO: ctx.data_inicio_curso || ctx.alvo_ddmmyyyy,
  DATA_AULA: ctx.alvo_ddmmyyyy,
  TEXTO_DATA: textoData,
  HORARIO: ctx.horario || '',
  ESPACO: c.ESPACO || '',
  FORMATO: c.FORMATO || '',
  PUBLICO_ALVO: c.PUBLICO_ALVO || '',
  PROFESSORES_TEXTO: profsTexto,
  TOTAL_ALUNOS: ctx.total_alunos || 0
};

const fila = [];
for (const a of (ctx.alunos || []))      fila.push({ ...base, tipo: 'ALUNO',     NOME: a.nome, EMAIL: a.email });
for (const p of (ctx.professores || [])) fila.push({ ...base, tipo: 'PROFESSOR', NOME: p.nome, EMAIL: p.email });

if (fila.length === 0) {
  // Sem destinatários — item sentinela para o loop fechar e ir ao próximo curso
  return [{ json: { ...base, tipo: 'VAZIO', NOME: '', EMAIL: '' } }];
}
return fila.map(f => ({ json: f }));

const ctx = $input.first().json;
console.log(`A data alvo não está na FREQUÊNCIA de: ${ctx.tema} (arquivo: ${ctx.arquivo?.name}). Curso ignorado.`);
return [{ json: ctx }];
